import { readFile, readdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { sql } from "drizzle-orm";

import type { Database } from "./client";

const DEFAULT_MIGRATIONS_DIR = fileURLToPath(
  new URL("../drizzle", import.meta.url),
);

/**
 * Applies the SQL files generated by `drizzle-kit generate` in order. This is
 * driver-agnostic (it works for postgres.js and PGlite) and is used to prepare
 * test databases and local environments. Production deployments run
 * `drizzle-kit migrate` instead, which tracks applied migrations in a table.
 */
export async function runMigrations(
  db: Database,
  migrationsDir: string = DEFAULT_MIGRATIONS_DIR,
): Promise<void> {
  const files = (await readdir(migrationsDir))
    .filter((file) => file.endsWith(".sql"))
    .sort();

  for (const file of files) {
    const content = await readFile(path.join(migrationsDir, file), "utf8");

    for (const statement of content.split("--> statement-breakpoint")) {
      const trimmed = statement.trim();
      if (trimmed.length > 0) {
        await db.execute(sql.raw(trimmed));
      }
    }
  }
}
